{"file_path":"tests/test_spec.py","content":""""Behavioral checks for each section of SPEC.md."""

import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def event(id_, day, flagged):
    return {"id": id_, "day": day, "flagged": flagged}


def test_section_1_none_values_count_in_denominator():
    assert monitor_flag_rate([event("a", 1, True), event("b", 1, None),
                              event("c", 1, False)]) == 1 / 3
    assert monitor_flag_rate([event("a", 1, None)]) == 0.0
    assert monitor_flag_rate([]) == 0.0


def test_section_2_pooled_rate_weights_transcripts_not_groups():
    groups = {"a": [event("a", 0, True)],
              "b": [event(str(i), 0, False) for i in range(3)], "empty": []}
    assert pooled_flag_rate(groups) == 0.25
    assert pooled_flag_rate({"empty": []}) == 0.0
    assert pooled_flag_rate({}) == 0.0


@pytest.mark.parametrize("days, expected", [(0, 0), (1, 4), (2, 7), (4, 10), (10, 10)])
def test_section_3_window(days, expected):
    assert flags_in_window([1, 2, 3, 4], days) == expected
    assert flags_in_window([], days) == 0


def test_section_4_parse_values_whitespace_and_skipped_lines():
    lines = ["\n", "   # comment, with commas\n", "  \t ",
             " x1 , 3 , 1 ", " x2, -2, 0", "x3, 0,  "]
    assert parse_transcript_log(lines) == [event("x1", 3, True),
                                           event("x2", -2, False),
                                           event("x3", 0, None)]


@pytest.mark.parametrize("bad_line", ["x,1", "x,1,1,extra", "x,no,1", "x,1,yes"])
def test_section_4_parse_errors_include_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_transcript_log(["", " # skipped", "ok,1,1", bad_line])


def test_section_5_duplicate_ids_keep_last_and_sort():
    old = event("a", 10, True)
    replacement = event("a", 2, None)
    b = event("b", 2, False)
    earlier = event("z", 1, True)
    assert dedupe_transcripts([old, b, earlier, replacement]) == [earlier, replacement, b]
    assert dedupe_transcripts([]) == []


def test_section_6_daily_counts_range_and_gaps():
    events = [event("a", 1, True), event("b", 2, True), event("c", 2, True),
              event("d", 2, None), event("e", 3, False), event("f", 5, True)]
    assert daily_flag_counts(events, 2, 4) == [2, 0, 0]
    assert daily_flag_counts(events, 3, 3) == [0]
    assert daily_flag_counts([], 1, 3) == [0, 0, 0]
    assert daily_flag_counts(events, 4, 2) == []


def test_section_7_summary_uses_calendar_days_and_nonempty_groups():
    groups = {"empty": [], "first": [event("a", 1, True)],
              "second": [event(str(i), 4, False) for i in range(5)]}
    assert monitor_summary(groups, 2) == {"rate": 0.167, "recent": 0, "groups": 2}
    assert monitor_summary(groups, 4) == {"rate": 0.167, "recent": 1, "groups": 2}
    assert monitor_summary(groups, 0)["recent"] == 0
    assert monitor_summary({"empty": []}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}
    assert monitor_summary({}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_section_8_top_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {"z": [event("a", 0, True)], "empty": [],
              "b": [event("b", 0, False)], "a": [event("c", 0, True)]}
    assert top_flagged_groups(groups, 2) == ["a", "z"]
    assert top_flagged_groups(groups, 10) == ["a", "z", "b"]
    assert top_flagged_groups(groups, 0) == []
    assert top_flagged_groups({}, 3) == []


def test_section_9_group_rates_sorted_and_empty_is_none():
    groups = {"z": [], "b": [event("b", 0, None)], "a": [event("a", 0, True)]}
    rates = flag_rate_by_group(groups)
    assert list(rates) == ["a", "b", "z"]
    assert rates == {"a": 1.0, "b": 0.0, "z": None}
    assert flag_rate_by_group({}) == {}


@pytest.mark.parametrize("counts, expected", [([], 0), ([0, -1, 0], 0),
                                               ([1, 2, 0, 1], 2),
                                               ([1, -1, 2, 3, 4], 3)])
def test_section_10_longest_positive_streak(counts, expected):
    assert longest_flag_streak(counts) == expected
